def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def main():
    source = base64.b64decode(CALIBRATION, validate=True)
    if hashlib.sha256(source).hexdigest() != CALIBRATION_SHA: raise RuntimeError('calibration hash mismatch')
    tree = ast.parse(source)
    assignments = {n.targets[0].id: n.value for n in tree.body if isinstance(n, ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0], ast.Name)}
    if ast.literal_eval(assignments['REVIEWED_AND_FROZEN']) is not False: raise RuntimeError('calibration guard changed')
    spec = importlib.util.find_spec('neural_lab.artifacts')
    if spec is None or spec.origin is None or digest(spec.origin) != HELPER_SHA: raise RuntimeError('helper mismatch')
    import numpy as np
    import torch
    import datasets, huggingface_hub, pyarrow, PIL
    from neural_lab.artifacts import ArtifactWriter, BestCheckpoint, load_json_state
    from neural_lab.runner import read_result
    science = base64.b64decode(ast.literal_eval(assignments['EMBEDDED_SOURCE']), validate=True)
    if hashlib.sha256(science).hexdigest() != ast.literal_eval(assignments['SOURCE_SHA']): raise RuntimeError('science mismatch')
    sci = types.ModuleType('synthetic_science')
    exec(compile(science, '<embedded-science>', 'exec'), sci.__dict__)
    # Execute the calibration's actual final publication statements in a private directory.
    main_fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == 'main')
    first = next(i for i,n in enumerate(main_fn.body) if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'result_bytes' for t in n.targets))
    publication = ast.Module(body=main_fn.body[first:], type_ignores=[])
    with tempfile.TemporaryDirectory(prefix='calibration-synthetic-') as temp:
        ROOT=Path(temp); OUT=ROOT/'calibration'; OUT.mkdir()
        writer=ArtifactWriter(OUT)
        raw=torch.zeros((2,3,32,32), dtype=torch.uint8)
        ids=torch.arange(2); mu=torch.zeros((1,3,1,1)); sd=torch.ones((1,3,1,1))
        data=writer.save_dataset('synthetic', {'images':raw.numpy(), 'ids':ids.numpy()}, provenance={'source':'synthetic zeros'})
        with np.load(OUT/data['path'], allow_pickle=False) as saved:
            if not np.array_equal(saved['images'],raw.numpy()): raise ValueError('dataset round trip')
        records=[]
        for arm in sci.ARMS:
            torch.manual_seed(4801); model=sci.Model(arm).eval()
            best=BestCheckpoint(scope='synthetic observations')
            best.observe(model, 2.0, 0); best.observe(model, 1.0, 1); best.observe(model, 1.0, 2)
            if best.step != 1: raise ValueError('earliest minimum')
            final=writer.save_checkpoint(arm+'-final',model,arm=arm,seed=4801,selection={'metric':'synthetic'},datasets=[data['path']])
            selected=best.save(writer,arm+'-selected',arm=arm,seed=4801,datasets=[data['path']])
            restored=sci.Model(arm).eval(); state=load_json_state(OUT/final['path']); restored.load_state_dict(state,strict=True)
            selected_state=load_json_state(OUT/selected['path'])
            if selected_state.keys()!=best.state.keys() or any(not torch.equal(selected_state[k],best.state[k]) for k in best.state): raise ValueError('selected state mismatch')
            with torch.no_grad():
                expected=model(sci.inputs(raw,ids,mu,sd)); actual=restored(sci.inputs(raw,ids,mu,sd))
                restored.load_state_dict(selected_state,strict=True); selected_actual=restored(sci.inputs(raw,ids,mu,sd))
            if not torch.isfinite(actual).all() or not torch.allclose(expected,actual,rtol=1e-5,atol=1e-6) or not torch.allclose(expected,selected_actual,rtol=1e-5,atol=1e-6): raise ValueError('checkpoint replay mismatch')
            records.append({'arm':arm})
        # Representative synthetic result lets the actual publisher exercise schema and inventory.
        (OUT/'calibration.json').write_text(json.dumps({'synthetic':True}))
        step=0; presentations=0
        namespace = dict(globals(), **locals())
        exec(compile(publication, '<actual-calibration-publication>', 'exec'), namespace)
        result=read_result(ROOT)
        if result['metrics']['arms_completed'] != 3: raise ValueError('result schema')
        inventory=json.loads((OUT/'integrity.json').read_text())
        for name, meta in inventory.items():
            path=OUT/name
            if path.stat().st_size != meta['bytes'] or digest(path) != meta['sha256']: raise ValueError('inventory mismatch: '+name)
        if (OUT/'.result.json.tmp').exists(): raise ValueError('temporary publication file remains')
        manifest=json.loads((OUT/'artifacts.json').read_text())
        for entry in manifest['datasets']+manifest['checkpoints']:
            path=OUT/entry['path']
            if path.stat().st_size != entry['bytes'] or digest(path)!=entry['sha256']: raise ValueError('manifest mismatch')
    output=Path('/output'); output.mkdir(parents=True,exist_ok=True)
    result={'metrics':{'arms_checked':3},'summary':'Offline synthetic calibration checkpoint and publication diagnostic passed; no training or data download.'}
    with (output/'result.json').open('x') as f: json.dump(result,f,allow_nan=False)

if __name__ == '__main__': main()
